import java.util.*;
class Calculator {
    private final String text;
    private int position;
    Calculator(String text) { this.text = text; }
    int evaluate() {
        return expression();
    }
    // 덧셈 단계예요. 무엇을 더하는지는 term 호출을 보세요.
    private int expression() {
        int value = factor();
        while (accept('+')) value += factor();
        return value;
    }
    // 곱셈 단계예요. factor가 돌려준 값을 곱해요.
    private int term() {
        int value = factor();
        while (accept('*')) value *= factor();
        return value;
    }
    // 숫자 단계예요. 이어진 숫자 글자를 정수 하나로 읽어요.
    private int factor() {
        int start = position;
        // 이번 작은 문법의 숫자는 ASCII 정수예요.
        while (position < text.length() && text.charAt(position) >= '0' && text.charAt(position) <= '9') position++;
        if (start == position) throw new IllegalArgumentException("number");
        return Integer.parseInt(text.substring(start, position));
    }
    // 원하는 기호가 있을 때만 읽기 위치를 한 칸 옮겨요.
    private boolean accept(char symbol) {
        if (position < text.length() && text.charAt(position) == symbol) {
            position++;
            return true;
        }
        return false;
    }
}

public class Main {
    public static void main(String[] args) {
        String text = new Scanner(System.in).nextLine();
        try { System.out.println(new Calculator(text).evaluate()); }
        catch (IllegalArgumentException error) { System.out.println("invalid"); }
    }
}

